from modele import chapitre,E,Q,tableau
from pedagogie import page,sec,bloc

chapitre(4,'division','Diviser et interpréter un partage','1 · Nombres et calculs',
'Partage · Groupement · Reste · Division décimale',
['Distinguer le calcul d’une part et le calcul d’un nombre de parts.','Effectuer une division euclidienne et une division décimale posées.','Interpréter un quotient, un reste ou une valeur approchée.'],
['Tables de multiplication ; multiples et diviseurs ; division posée du CM2.'],[
page(1,'Deux sens pour une division',
bloc('definition',r'Une division répond à deux sortes de questions. Partage : 84 bonbons sont partagés également entre 6 enfants ; on cherche la valeur d’une part. Groupement : 84 bonbons sont rangés en sachets de 6 ; on cherche le nombre de parts. Le même calcul $84:6=14$ répond aux deux questions.'),
r'@FIG:cours-partage@',
sec(2,'Division euclidienne et reste'),
bloc('definition',r'Effectuer la division euclidienne d’un entier $a$ par un entier $b$ non nul, c’est trouver le quotient $q$ et le reste $r$ tels que $a=b\times q+r$, avec $r<b$. Par exemple $487=23\times21+4$ et $4<23$ : le quotient est 21 et le reste est 4.'),
bloc('savoirfaire',r'Pour $487:23$, on encadre : $23\times20=460$ et $23\times30=690$, donc le quotient s’écrit avec deux chiffres et commence par 2. Puis $487-460=27$, qui contient encore une fois 23 : quotient 21, reste $27-23=4$.','Encadrer par des multiples')),
page(3,'Division décimale par un entier',
bloc('savoirfaire',r'Pour $23:4$ : 23 unités divisées par 4 donnent 5 unités ; il reste 3 unités, soit 30 dixièmes. 30 dixièmes divisés par 4 donnent 7 dixièmes ; il reste 2 dixièmes, soit 20 centièmes. 20 centièmes divisés par 4 donnent 5 centièmes, reste 0. Donc $23:4=5{,}75$.','Poursuivre après la virgule'),
r'@FIG:cours-potence@',
bloc('exemple',r'$47{,}6:4$ : on divise les unités, puis les dixièmes. On trouve $11{,}9$. Contrôle : $11{,}9\times4=47{,}6$.'),
sec(4,'Résultat exact et division qui se poursuit'),
bloc('propriete',r'Parfois la division s’arrête avec un reste nul : le quotient est exact. Parfois le même reste revient sans fin : $10:3=3{,}333\ldots$ On donne alors une valeur arrondie, par exemple $3{,}33$ au centième.'),
bloc('attention',r'Le reste se lit dans l’histoire. 50 élèves partent en minibus de 12 places : $50=12\times4+2$. Il faut 5 minibus, car les 2 élèves restants doivent aussi voyager.')),
],[
E('Part ou nombre de parts ?',r'Pour chaque problème, dire si l’on cherche la valeur d’une part ou le nombre de parts, puis le résoudre.'+Q(r'96 cartes sont partagées également entre 8 joueurs. Combien de cartes chacun reçoit-il ?',r'96 cartes sont rangées en paquets de 8. Combien de paquets obtient-on ?'),r'1. Valeur d’une part : $96:8=\res{12}$ cartes par joueur. 2. Nombre de parts : $96:8=\res{12}$ paquets. Le calcul est le même, la question non.','Se demander ce que l’on cherche.','assert 96//8==12 and 96%8==0'),
E('Division euclidienne',r'Effectuer la division euclidienne de 487 par 23, puis de $1\,000$ par 7. Écrire chaque fois l’égalité obtenue.',r'$\res{487=23\times21+4}$, avec $4<23$. $\res{1\,000=7\times142+6}$, avec $6<7$.','Encadrer par des multiples du diviseur.','assert divmod(487,23)==(21,4) and divmod(1000,7)==(142,6)'),
E('La bonne égalité',r'Laquelle de ces égalités traduit la division euclidienne de 158 par 12 ? $158=12\times13+2$ ; $158=12\times12+14$ ; $158=12\times11+26$.',r'Les trois égalités sont justes, mais le reste doit être plus petit que 12 : seule $\res{158=12\times13+2}$ convient. Quotient 13, reste 2.','Vérifier que le reste est plus petit que le diviseur.','assert 12*13+2==12*12+14==12*11+26==158 and divmod(158,12)==(13,2)'),
E('Division décimale',r'Poser et calculer $47{,}6:4$, puis $9{,}45:5$.',r'$47{,}6:4=\res{11{,}9}$ ; $9{,}45:5=\res{1{,}89}$. Contrôles : $11{,}9\times4=47{,}6$ et $1{,}89\times5=9{,}45$.','Diviser rang par rang en plaçant la virgule au passage des unités.','assert Rational("47.6")/4==Rational("11.9") and Rational("9.45")/5==Rational("1.89")'),
E('Après la virgule',r'Calculer le quotient décimal exact de $23:4$, puis de $7:8$.',r'$23:4=\res{5{,}75}$. Pour $7:8$ : 70 dixièmes donnent 8 dixièmes, reste 6 ; 60 centièmes donnent 7 centièmes, reste 4 ; 40 millièmes donnent 5 millièmes, reste 0 : $\res{0{,}875}$.','Transformer le reste en dixièmes, puis en centièmes.','assert Rational(23,4)==Rational("5.75") and Rational(7,8)==Rational("0.875")'),
E('Une division posée',r'Recopier et compléter la division posée de 365 par 8, puis écrire l’égalité de la division euclidienne.',r'Dans 36 dizaines, il y a 4 fois 8 : reste 4 dizaines. 45 unités contiennent 5 fois 8 : reste 5. Quotient $45$, reste $5$ : $\res{365=8\times45+5}$.','Diviser les dizaines, puis les unités.','assert divmod(365,8)==(45,5) and 36-32==4 and 45-40==5',figure='div-6'),
E('Le reste dans l’histoire',r'50 élèves partent en sortie dans des minibus de 12 places. Combien de minibus faut-il ? Combien de places restent libres ?',r'$50=12\times4+2$. Quatre minibus ne suffisent pas : il en faut $\res5$. Places libres : $5\times12-50=\res{10}$.','Interpréter le reste dans la situation.','assert divmod(50,12)==(4,2) and 5*12-50==10'),
E('Une division sans fin',r'Calculer $10:3$ et $2:3$ en poursuivant après la virgule. Que remarque-t-on ? Donner l’arrondi au centième de chaque quotient.',r'Pour $10:3$, le reste 1 revient toujours : $3{,}333\ldots$ Pour $2:3$, le reste 2 revient : $0{,}666\ldots$ Les divisions ne s’arrêtent pas. Arrondis : $\res{3{,}33}$ et $\res{0{,}67}$.','Repérer un reste qui se répète.','assert abs(Rational(10,3)-Rational("3.33"))<Rational(1,200) and abs(Rational(2,3)-Rational("0.67"))<Rational(1,200)'),
E('Partager au centime',r'25 € sont partagés également entre 4 amis, puis 17 € entre 6 amis. Les partages tombent-ils juste au centime près ?',r'$25:4=\res{6{,}25}$ € : partage exact. $17:6=2{,}833\ldots$ : chacun reçoit $\res{2{,}83}$ € et il reste $17-6\times2{,}83=0{,}02$ €, soit 2 centimes.','Diviser, puis contrôler par une multiplication.','assert Rational(25,4)==Rational("6.25") and 17-6*Rational("2.83")==Rational("0.02")'),
E('Retrouver le dividende',r'Dans une division euclidienne, le diviseur est 15, le quotient 23 et le reste 9. Quel est le dividende ? Le reste aurait-il pu valoir 15 ?',r'Dividende : $15\times23+9=\res{354}$. Le reste ne peut pas valoir 15 : il doit être plus petit que le diviseur, sinon on pourrait faire un paquet de plus.','Utiliser l’égalité dividende = diviseur × quotient + reste.','assert 15*23+9==354 and divmod(354,15)==(23,9)'),
E('Les boîtes d’œufs',r'Une ferme ramasse $1\,000$ œufs dans la journée. Elle les range dans des boîtes de 6. Combien de boîtes pleines obtient-elle ? Combien de boîtes faut-il pour emballer tous les œufs ?',r'$1\,000=6\times166+4$ : $\res{166}$ boîtes pleines et 4 œufs restants. Pour tout emballer, il faut une boîte de plus : $\res{167}$ boîtes.','Quotient, puis interprétation du reste.','assert divmod(1000,6)==(166,4)'),
E('L’addition du restaurant',r'Sept amis partagent également une addition de $94{,}50$ €. Combien chacun paie-t-il ?',r'$94{,}5:7=\res{13{,}5}$, soit $13{,}50$ € chacun. Contrôle : $13{,}5\times7=94{,}5$.','Division décimale par un entier inférieur à 10.','assert Rational("94.5")/7==Rational("13.5")'),
E('La randonnée',r'Une randonnée de $38{,}4$ km se fait en 3 jours de même longueur. Quelle distance par jour ? On la découpe ensuite en 8 étapes égales : quelle est la longueur d’une étape ?',r'$38{,}4:3=\res{12{,}8}$ km par jour. $38{,}4:8=\res{4{,}8}$ km par étape.','Chercher la valeur d’une part.','assert Rational("38.4")/3==Rational("12.8") and Rational("38.4")/8==Rational("4.8")'),
E('Quel jour sera-t-il ?',r'Nous sommes lundi. Quel jour de la semaine serons-nous dans 100 jours ?',r'$100=7\times14+2$ : 14 semaines complètes ramènent au lundi, puis 2 jours de plus. Ce sera un $\res{\text{mercredi}}$.','Les semaines complètes ne changent pas le jour.','assert divmod(100,7)==(14,2)'),
E('Le plus grand reste',r'Dans une division euclidienne par 24, quel est le plus grand reste possible ? Trouver le plus grand nombre inférieur à 500 qui donne ce reste.',r'Le reste est plus petit que 24 : au plus $\res{23}$. Les nombres cherchés s’écrivent $24\times q+23$ : $24\times20+23=503$ dépasse 500, donc la réponse est $24\times19+23=\res{479}$.','Écrire le nombre sous la forme diviseur × quotient + reste.','assert max(n for n in range(500) if n%24==23)==479')
],reperes=['Sens de la division : partage ou groupement','Division euclidienne et reste','Division décimale par un entier','Interpréter un quotient, un reste, une valeur approchée'],deco='calcul')

chapitre(5,'fraction-quotient','Les fractions comme nombres','1 · Nombres et calculs',
'Quotient · Égalités à trous · Demi-droite · Nombres mixtes',
['Comprendre une fraction comme le résultat exact d’une division.','Placer des fractions sur une demi-droite et graduer un segment.','Reconnaître une fraction entière, décimale ou non décimale.'],
['Fractions du cours moyen : parts égales, fractions plus grandes que 1.'],[
page(1,'De la part d’un tout au quotient',
bloc('definition',r'Si $b$ n’est pas nul, le quotient de $a$ par $b$ est le nombre qui, multiplié par $b$, donne $a$. On le note $\frac ab$ : c’est le résultat exact de la division de $a$ par $b$. Ainsi $4\times\frac34=3$.'),
r'@FIG:cours-quart-de-3@',
bloc('propriete',r'$\frac34$ désigne à la fois trois quarts d’une unité et le quart de 3 unités : les deux lectures donnent la même longueur. Une fraction est un nombre.'),
sec(2,'Compléter une égalité multiplicative'),
bloc('savoirfaire',r'$7\times\square=3$ : le nombre cherché est $\frac37$, par définition du quotient. $\square\times4=3$ : c’est $\frac34$. $6\times\square=18$ : c’est $\frac{18}6$, soit 3.','Égalités à trous')),
page(3,'Repérer des fractions sur une demi-droite',
bloc('savoirfaire',r'Pour placer $\frac74$, on partage l’unité en 4 et on compte 7 pas d’un quart : on dépasse 1 de trois quarts, car $\frac74=1+\frac34$.','Placer une fraction'),
r'@FIG:cours-droite-quarts@',
bloc('savoirfaire',r'Pour partager un segment en 7 parts égales sans mesurer, on le pose sur un réseau de droites parallèles également espacées, appelé guide-âne : les droites le coupent en 7 parts égales.','Graduer un segment'),
r'@FIG:cours-guide-ane@',
sec(4,'Fractions, décimaux et nombres mixtes'),
bloc('propriete',r'Une fraction peut désigner un entier, $\frac{12}4=3$ ; un décimal non entier, $\frac34=0{,}75$ ; ou un nombre non décimal, comme $\frac13$ : $3\times0{,}3=0{,}9$ ; $3\times0{,}33=0{,}99$… on n’atteint jamais 1. À connaître : $\frac14=0{,}25$ ; $\frac12=0{,}5$ ; $\frac34=0{,}75$ ; $\frac32=1{,}5$ ; $\frac42=2$ ; $\frac52=2{,}5$.')),
],[
E('Quotient exact',r'Écrire sous forme de fraction le résultat exact de $5:8$, de $13:4$ et de $2:7$. Lesquels sont des nombres décimaux ?',r'$\res{\frac58}$ ; $\res{\frac{13}4}$ ; $\res{\frac27}$. $\frac58=0{,}625$ et $\frac{13}4=3{,}25$ sont décimaux ; la division de 2 par 7 ne s’arrête pas : $\frac27$ n’est pas décimal.','Le quotient exact s’écrit avec une fraction.','assert Rational(5,8)==Rational("0.625") and Rational(13,4)==Rational("3.25") and 1000000*Rational(2,7)!=int(1000000*Rational(2,7))'),
E('Égalités à trous',r'Compléter : $9\times\square=4$ ; $\square\times5=3$ ; $11\times\square=11$ ; $6\times\square=18$.',r'$\square=\res{\frac49}$ ; $\square=\res{\frac35}$ ; $\square=\res1$ ; $\square=\res{\frac{18}6}=3$.','Le nombre qui multiplié par b donne a est a sur b.','assert 9*Rational(4,9)==4 and Rational(3,5)*5==3 and 11*1==11 and 6*Rational(18,6)==18'),
E('À connaître',r'Donner l’écriture décimale de $\frac14$ ; $\frac34$ ; $\frac32$ ; $\frac52$ ; $\frac42$, puis une fraction égale à $0{,}5$.',r'$\res{0{,}25}$ ; $\res{0{,}75}$ ; $\res{1{,}5}$ ; $\res{2{,}5}$ ; $\res2$. Et $0{,}5=\res{\frac12}$.','Automatismes du programme.','assert Rational(1,4)==Rational(".25") and Rational(3,4)==Rational(".75") and Rational(3,2)==Rational("1.5") and Rational(5,2)==Rational("2.5") and Rational(4,2)==2 and Rational(".5")==Rational(1,2)'),
E('Lire sur la droite',r'L’unité est partagée en quarts. Lire les abscisses des points A, B et C sous forme de fraction, puis de nombre mixte quand c’est utile.',r'A : $\res{\frac34}$. B : $\res{\frac74}=1+\frac34$. C : $\res{\frac{10}4}=2+\frac24$, soit $2+\frac12$.','Compter les pas d’un quart depuis 0.','assert Rational(7,4)==1+Rational(3,4) and Rational(10,4)==2+Rational(1,2)',figure='fq-4'),
E('Le quart de 3',r'La bande mesure 3 unités. Elle est partagée en 4 parts égales. Quelle est la longueur d’une part ? Comparer avec trois quarts d’unité.',r'Une part mesure $3:4=\res{\frac34}$ d’unité : quatre parts de $\frac34$ font bien $4\times\frac34=3$. C’est exactement trois quarts d’une unité.','Une fraction est le quotient du numérateur par le dénominateur.','assert 4*Rational(3,4)==3',figure='fq-5'),
E('Placer des fractions',r'L’unité est partagée en sixièmes. Placer les points D, E et F d’abscisses $\frac56$ ; $\frac{11}6$ et $\frac43$.',r'D : 5 pas d’un sixième. E : 11 pas, soit $1+\frac56$. F : $\frac43=\frac86$, soit 8 pas, $1+\frac26$. Les points figurent en vert.','Écrire chaque fraction en sixièmes.','assert Rational(4,3)==Rational(8,6) and Rational(11,6)==1+Rational(5,6)',figure='fq-6'),
E('Entier, décimal ou non décimal',r'Classer en trois groupes, entiers, décimaux non entiers et non décimaux : $\frac{15}5$ ; $\frac74$ ; $\frac23$ ; $\frac9{10}$ ; $\frac56$.',r'Entier : $\res{\frac{15}5=3}$. Décimaux non entiers : $\res{\frac74=1{,}75}$ et $\res{\frac9{10}=0{,}9}$. Non décimaux : $\res{\frac23}$ et $\res{\frac56}$, car les divisions ne s’arrêtent pas.','Effectuer la division du numérateur par le dénominateur.','assert Rational(15,5)==3 and Rational(7,4)==Rational("1.75") and Rational(9,10)==Rational(".9") and all(10**6*q!=int(10**6*q) for q in [Rational(2,3),Rational(5,6)])'),
E('Nombres mixtes',r'Écrire $\frac{17}5$ et $\frac{23}6$ sous la forme d’un entier plus une fraction plus petite que 1, puis écrire $3+\frac27$ avec une seule fraction.',r'$\frac{17}5=\res{3+\frac25}$ ; $\frac{23}6=\res{3+\frac56}$ ; $3+\frac27=\frac{21}7+\frac27=\res{\frac{23}7}$.','Extraire les unités entières.','assert Rational(17,5)==3+Rational(2,5) and Rational(23,6)==3+Rational(5,6) and 3+Rational(2,7)==Rational(23,7)'),
E('Graduer un segment',r'Le segment [AB] mesure 5 cm. À l’aide du réseau de droites parallèles également espacées, le partager en 3 parts égales. Quelle est la longueur exacte d’une part ? Donner son arrondi au centième.',r'Les droites du réseau coupent le segment [AB] en trois parts égales, marquées en vert. Une part mesure $\res{\frac53}$ cm, soit environ $\res{1{,}67}$ cm.','Utiliser le guide-âne plutôt que la règle graduée.','assert 3*Rational(5,3)==5 and abs(Rational(5,3)-Rational("1.67"))<Rational(1,200)',figure='fq-9'),
E('Encadrer entre deux entiers',r'Encadrer chaque fraction entre deux entiers consécutifs : $\frac{17}3$ ; $\frac{47}{10}$ ; $\frac{22}7$.',r'$15<17<18$ : $\res{5<\frac{17}3<6}$. $\res{4<\frac{47}{10}<5}$. $21<22<28$ : $\res{3<\frac{22}7<4}$.','Encadrer le numérateur par des multiples du dénominateur.','assert 5<Rational(17,3)<6 and 4<Rational(47,10)<5 and 3<Rational(22,7)<4'),
E('Le partage des pizzas',r'À une table, 3 pizzas sont partagées également entre 4 enfants. À une autre, 5 pizzas entre 8 enfants. Quelle part de pizza reçoit chaque enfant ? À quelle table mange-t-on le plus ?',r'Première table : $3:4=\res{\frac34}$ de pizza. Seconde : $5:8=\res{\frac58}$. Or $\frac34=\frac68>\frac58$ : on mange plus à la $\res{\text{première table}}$.','La part est le quotient du nombre de pizzas par le nombre d’enfants.','assert Rational(3,4)==Rational(6,8)>Rational(5,8)'),
E('La ficelle',r'Une ficelle de 2 m est coupée en 5 morceaux égaux, une autre de 2 m en 3 morceaux égaux. Donner la longueur exacte d’un morceau dans chaque cas, puis une écriture décimale exacte ou arrondie au centième.',r'$\frac25=\res{0{,}4}$ m, valeur exacte. $\frac23$ m n’est pas décimal : environ $\res{0{,}67}$ m.','Distinguer valeur exacte et valeur approchée.','assert Rational(2,5)==Rational(".4") and abs(Rational(2,3)-Rational(".67"))<Rational(1,200)'),
E('Le nombre caché',r'Quel nombre faut-il multiplier par 8 pour obtenir 6 ? Donner son écriture fractionnaire la plus simple et son écriture décimale.',r'C’est $\frac68$, qui se simplifie en $\res{\frac34}$, soit $\res{0{,}75}$. Contrôle : $8\times0{,}75=6$.','Utiliser la définition du quotient.','assert 8*Rational(6,8)==6 and Rational(6,8)==Rational(3,4)==Rational(".75")'),
E('Les nombres rompus',r'Au Moyen Âge, on appelait les fractions des « nombres rompus ». Un champ de 7 arpents est partagé également entre 3 héritiers. Quelle part reçoit chacun ? L’écrire comme nombre mixte, puis donner son arrondi au dixième.',r'Chacun reçoit $\res{\frac73}$ d’arpent, soit $\res{2+\frac13}$ arpents. Comme $\frac13=0{,}333\ldots$, l’arrondi au dixième est $\res{2{,}3}$.','Le partage exact s’écrit avec une fraction.','assert 3*Rational(7,3)==7 and Rational(7,3)==2+Rational(1,3) and abs(Rational(7,3)-Rational("2.3"))<Rational(1,20)'),
E('Vrai ou faux',r'Sacha affirme : « $\frac13=0{,}33$. » A-t-il raison ? Justifier par une multiplication.',r'$\res{\text{Non}}$ : $3\times0{,}33=0{,}99$, qui n’est pas égal à 1. $0{,}33$ n’est qu’une valeur approchée de $\frac13$ ; on écrit $\frac13\approx0{,}33$.','Utiliser la définition : 3 fois un tiers égale 1.','assert 3*Rational(".33")==Rational(".99") and 3*Rational(1,3)==1')
],reperes=['Fraction quotient et égalités à trous','Fractions sur une demi-droite et graduations','Entier, décimal ou non décimal','Nombres mixtes et problèmes de partage'],deco='calcul')

chapitre(6,'calcul-fractions','Comparer et calculer des fractions','1 · Nombres et calculs',
'Égalités · Comparaisons · Sommes · Produit par un entier',
['Établir des égalités de fractions et simplifier.','Comparer, encadrer et ranger des fractions et des nombres mixtes.','Additionner, soustraire, multiplier par un entier et appliquer une fraction.'],
['Fraction quotient ; tables, multiples et diviseurs.'],[
page(1,'Fractions égales et simplification',
bloc('propriete',r'On ne change pas une fraction en multipliant, ou en divisant, son numérateur et son dénominateur par un même nombre non nul : $\frac23=\frac{2\times4}{3\times4}=\frac8{12}$ ; $\frac{18}{24}=\frac{18:6}{24:6}=\frac34$.'),
r'@FIG:cours-bandes-egales@',
bloc('savoirfaire',r'On cherche un diviseur commun grâce aux tables : 18 et 24 sont dans la table de 6. On peut aussi simplifier en plusieurs fois : $\frac{18}{24}=\frac9{12}=\frac34$.','Simplifier'),
sec(2,'Comparer, encadrer et ranger'),
bloc('propriete',r'Avec le même dénominateur, la plus grande fraction a le plus grand numérateur. Sinon, on se ramène au même dénominateur : $\frac56=\frac{10}{12}>\frac7{12}$. Avec le même numérateur, la plus grande a le plus petit dénominateur : $\frac45>\frac49$.'),
bloc('exemple',r'Pour ranger $\frac74$, $\frac32$ et $1+\frac18$, on écrit tout en huitièmes : $\frac{14}8$, $\frac{12}8$ et $\frac98$. Donc $1+\frac18<\frac32<\frac74$.')),
page(3,'Additionner et soustraire des fractions',
bloc('propriete',r'Pour additionner ou soustraire des fractions, on les écrit avec le même dénominateur, puis on ajoute ou on retranche les numérateurs : $\frac34+\frac18=\frac68+\frac18=\frac78$ ; $\frac23+\frac14=\frac8{12}+\frac3{12}=\frac{11}{12}$.'),
bloc('exemple',r'À savoir sans calcul : $\frac12+\frac12=1$ ; $\frac14+\frac14=\frac12$ ; $1-\frac14=\frac34$ ; $\frac12+\frac14=\frac34$ ; $1-\frac12=\frac12$ ; $\frac34+\frac14=1$ ; $\frac12-\frac14=\frac14$ ; $\frac34-\frac14=\frac12$.'),
bloc('attention',r'On n’additionne jamais les dénominateurs : $\frac14+\frac14$ vaut $\frac24$, deux quarts, et non $\frac28$.'),
sec(4,'Multiplier par un entier, appliquer une fraction'),
bloc('propriete',r'$7\times\frac14=\frac74$ : sept fois un quart. C’est aussi $\frac14\times7$, le quart de 7. De même $5\times\frac23=\frac{10}3$ : on multiplie le numérateur par l’entier.'),
bloc('savoirfaire',r'$\frac23$ de 12, c’est $\frac23\times12$ : $12:3\times2=8$. De même, $\frac34$ de 10 m vaut $10:4\times3=7{,}5$ m.','Prendre une fraction d’un nombre')),
],[
E('Fractions égales',r'Compléter : $\frac23=\frac{\square}{12}$ ; $\frac54=\frac{20}{\square}$ ; $\frac{18}{24}=\frac3{\square}$.',r'$\times4$ : $\res{8}$. $\times4$ : $\res{16}$. $:6$ : $\res4$.','Chercher par quel nombre on multiplie ou on divise.','assert Rational(2,3)==Rational(8,12) and Rational(5,4)==Rational(20,16) and Rational(18,24)==Rational(3,4)'),
E('Simplifier',r'Simplifier le plus possible : $\frac{15}{20}$ ; $\frac{24}{36}$ ; $\frac{45}{10}$.',r'$\frac{15}{20}=\res{\frac34}$ (division par 5) ; $\frac{24}{36}=\res{\frac23}$ (par 12) ; $\frac{45}{10}=\res{\frac92}$ (par 5).','Diviser par un diviseur commun.','assert Rational(15,20)==Rational(3,4) and Rational(24,36)==Rational(2,3) and Rational(45,10)==Rational(9,2)'),
E('Comparer',r'Comparer avec $<$ ou $>$ : $\frac57$ et $\frac37$ ; $\frac56$ et $\frac7{12}$ ; $\frac45$ et $\frac49$ ; $\frac98$ et 1.',r'$\res{\frac57>\frac37}$ ; $\frac56=\frac{10}{12}$ donc $\res{\frac56>\frac7{12}}$ ; $\res{\frac45>\frac49}$ ; $\res{\frac98>1}$, car $9>8$.','Même dénominateur, même numérateur ou comparaison à 1.','assert Rational(5,7)>Rational(3,7) and Rational(5,6)>Rational(7,12) and Rational(4,5)>Rational(4,9) and Rational(9,8)>1'),
E('Calcul mental',r'Calculer : $\frac12+\frac14$ ; $1-\frac14$ ; $\frac34-\frac12$ ; $\frac14+\frac14+\frac12$.',r'$\res{\frac34}$ ; $\res{\frac34}$ ; $\res{\frac14}$ ; $\res1$.','Penser en quarts.','assert Rational(1,2)+Rational(1,4)==Rational(3,4) and 1-Rational(1,4)==Rational(3,4) and Rational(3,4)-Rational(1,2)==Rational(1,4) and Rational(1,4)+Rational(1,4)+Rational(1,2)==1'),
E('Fraction d’un nombre',r'Calculer : $\frac23$ de 12 ; $\frac34$ de 10 ; $\frac15$ de 35.',r'$12:3\times2=\res8$ ; $10:4\times3=\res{7{,}5}$ ; $35:5=\res7$.','Diviser par le dénominateur, multiplier par le numérateur.','assert Rational(2,3)*12==8 and Rational(3,4)*10==Rational("7.5") and Rational(1,5)*35==7'),
E('Ranger',r'Ranger dans l’ordre croissant : $\frac74$ ; $\frac32$ ; $1+\frac18$ ; $\frac{15}8$.',r'En huitièmes : $\frac{14}8$ ; $\frac{12}8$ ; $\frac98$ ; $\frac{15}8$. Ordre : $\res{1+\frac18<\frac32<\frac74<\frac{15}8}$.','Tout écrire avec le même dénominateur.','L=[1+Rational(1,8),Rational(3,2),Rational(7,4),Rational(15,8)]\nassert L==sorted(L)'),
E('Sommes et différences',r'Calculer : $\frac34+\frac58$ ; $\frac{11}{12}-\frac13$ ; $\frac23+\frac14$.',r'$\frac68+\frac58=\res{\frac{11}8}$ ; $\frac{11}{12}-\frac4{12}=\res{\frac7{12}}$ ; $\frac8{12}+\frac3{12}=\res{\frac{11}{12}}$.','Écrire d’abord avec un même dénominateur.','assert Rational(3,4)+Rational(5,8)==Rational(11,8) and Rational(11,12)-Rational(1,3)==Rational(7,12) and Rational(2,3)+Rational(1,4)==Rational(11,12)'),
E('Multiplier par un entier',r'Calculer : $7\times\frac14$ ; $5\times\frac23$ ; $6\times\frac56$ ; $\frac14\times7$.',r'$\res{\frac74}$ ; $\res{\frac{10}3}$ ; $\frac{30}6=\res5$ ; $\res{\frac74}$ : le quart de 7 est égal à 7 fois un quart.','Multiplier le numérateur par l’entier.','assert 7*Rational(1,4)==Rational(7,4) and 5*Rational(2,3)==Rational(10,3) and 6*Rational(5,6)==5'),
E('Sur une même droite',r'L’unité est partagée en douzièmes. Écrire les abscisses de A, B et C en douzièmes, les simplifier, puis ranger les trois nombres.',r'A : $\frac9{12}=\res{\frac34}$. B : $\frac{10}{12}=\res{\frac56}$. C : $\frac{16}{12}=\res{\frac43}$. Ordre : $\res{\frac34<\frac56<\frac43}$.','Compter les pas, puis simplifier.','assert Rational(9,12)==Rational(3,4) and Rational(10,12)==Rational(5,6) and Rational(16,12)==Rational(4,3) and Rational(3,4)<Rational(5,6)<Rational(4,3)',figure='fc-9'),
E('Égales ou pas ?',r'Les fractions $\frac69$ et $\frac{10}{15}$ sont-elles égales ? Et $\frac46$ et $\frac68$ ?',r'$\frac69=\frac23$ et $\frac{10}{15}=\frac23$ : $\res{\text{égales}}$. $\frac46=\frac23=\frac8{12}$ et $\frac68=\frac34=\frac9{12}$ : $\res{\text{différentes}}$.','Simplifier les deux fractions.','assert Rational(6,9)==Rational(10,15) and Rational(4,6)!=Rational(6,8)'),
E('Le gâteau',r'Emma mange le quart d’un gâteau et Lucas le tiers. Quelle fraction du gâteau ont-ils mangée ensemble ? Quelle fraction reste-t-il ?',r'$\frac14+\frac13=\frac3{12}+\frac4{12}=\res{\frac7{12}}$. Il reste $1-\frac7{12}=\res{\frac5{12}}$ du gâteau.','Additionner en douzièmes.','assert Rational(1,4)+Rational(1,3)==Rational(7,12) and 1-Rational(7,12)==Rational(5,12)'),
E('La cantine',r'Dans une classe de 28 élèves, les trois quarts déjeunent à la cantine. Combien d’élèves déjeunent à la cantine ? Quelle fraction de la classe ne s’y rend pas, et combien d’élèves cela représente-t-il ?',r'$\frac34\times28=28:4\times3=\res{21}$ élèves. Fraction restante : $1-\frac34=\res{\frac14}$, soit $\res7$ élèves.','Appliquer la fraction au nombre d’élèves.','assert Rational(3,4)*28==21 and (1-Rational(3,4))*28==7'),
E('La recette',r'Une recette pour 4 personnes demande $\frac34$ de litre de lait. Quelle quantité faut-il pour 12 personnes ? Donner le résultat en fraction, puis en écriture décimale.',r'12 personnes, c’est 3 fois plus : $3\times\frac34=\res{\frac94}$ L, soit $\res{2{,}25}$ L.','Multiplier une fraction par un entier.','assert 3*Rational(3,4)==Rational(9,4)==Rational("2.25")'),
E('Le réservoir',r'Un réservoir de 60 L est rempli aux $\frac56$. On utilise ensuite une quantité égale au quart du réservoir plein. Combien de litres restent ? Quelle fraction du réservoir plein cela représente-t-il ?',r'Au départ : $\frac56\times60=50$ L. On utilise $\frac14\times60=15$ L : il reste $\res{35}$ L. Fraction : $\frac56-\frac14=\frac{10}{12}-\frac3{12}=\res{\frac7{12}}$, et $\frac7{12}\times60=35$.','Calculer en litres, puis contrôler avec les fractions.','assert Rational(5,6)*60-Rational(1,4)*60==35 and Rational(5,6)-Rational(1,4)==Rational(7,12) and Rational(7,12)*60==35'),
E('Inventer un problème',r'Inventer un problème dont la solution est le calcul « $\frac25$ de 30 », puis le résoudre.',r'Exemple : « Dans un club de 30 enfants, les deux cinquièmes font du judo. Combien d’enfants font du judo ? » Réponse : $30:5\times2=\res{12}$ enfants. Toute situation où l’on prend les $\frac25$ d’une quantité de 30 convient.','Partir du calcul pour imaginer une situation.','assert Rational(2,5)*30==12')
],reperes=['Fractions égales et simplification','Comparer, encadrer et ranger','Additionner et soustraire','Multiplier par un entier, appliquer une fraction'],deco='calcul')
